const listSupplierPayments = `-- name: ListSupplierPayments :many
SELECT 
    p.id, p.legal_entity_id, p.payment_number, p.supplier_id, p.payment_date, p.payment_method, p.disbursement_account_id, p.amount, p.currency_code, p.reference_number, p.status, p.notes, p.allocated_amount, p.unallocated_amount, p.journal_entry_id, p.created_by_user_id, p.created_at,
    s.name_en AS supplier_name_en,
    s.name_ar AS supplier_name_ar,
    s.supplier_number
FROM payables.payments p
JOIN payables.suppliers s ON p.supplier_id = s.id
WHERE p.legal_entity_id = $1
  AND ($2::uuid IS NULL OR p.supplier_id = $2)
  AND (
      $3::text = '' 
      OR p.payment_number ILIKE '%' || $3 || '%'
      OR p.reference_number ILIKE '%' || $3 || '%'
      OR s.name_en ILIKE '%' || $3 || '%'
      OR s.name_ar ILIKE '%' || $3 || '%'
  )
ORDER BY p.payment_date DESC, p.created_at DESC
LIMIT $4 OFFSET $5
`

